// 01 Config & Memory — central configuration + weighted category/style rotation + content memory.
// Everything tunable lives in CONFIG. Webhook body (Manual Fire) can override: {batch, publish, categories:[...]}.
const CONFIG = {
  PLATFORM: 'facebook',
  BATCH_SIZE: 1,                    // posts per execution (1/5/10/20)
  CAPTION_LENGTH: 'rotate',         // 'short' | 'medium' | 'long' | 'rotate'
  IMAGE_ASPECT_RATIO: '4:5',        // '4:5' | '2:3' | '1:1' | '9:16'
  QUALITY_THRESHOLD: 80,            // publish gate (0-100)
  SIMILARITY_THRESHOLD: 0.55,       // Jaccard overlap that flags a duplicate
  MAX_RETRIES: 0,                   // auto-regeneration rounds (0 = reject & log with critique)
  CTA_FREQUENCY: 0.4,               // ~40% of posts get a natural CTA
  HASHTAG_LIMIT: 8,                 // 5-10, never stuffed
  TREND_RESEARCH_ENABLED: true,     // use live Pinterest/HN titles as trend context
  AUTO_PUBLISH_ENABLED: true,       // LIVE daily flow — Manual Fire {"publish":false} for dry runs
  IMAGE_SIZE: '1024x1536',          // gpt-image-2 vertical (2:3)
  CONTENT_LANGUAGE: 'en',
  MEMORY_LIMIT: 200                 // keep last N content records
};

const ASPECTS = { '4:5': [1000, 1250], '2:3': [1000, 1500], '1:1': [1080, 1080], '9:16': [810, 1440] };

// 20-category editorial system (weights sum ~100).
const CATEGORIES = [
  { id: 'quiet_ambition', name: 'Quiet Ambition', weight: 10, core: 'Build without needing constant validation.', subs: ['building privately', 'silent progress', 'results over announcements', 'ambition without performance', 'letting results speak', 'long-term thinking', 'sustainable ambition'] },
  { id: 'discipline_no_hustle', name: 'Discipline Without Hustle', weight: 8, core: 'Discipline without burnout or toxic productivity.', subs: ['keeping promises to yourself', 'discipline without motivation', 'rest as part of discipline', 'showing up on difficult days', 'identity-based habits', 'boring consistent work'] },
  { id: 'ai_era_growth', name: 'AI-Era Self Improvement', weight: 10, core: 'How humans should develop themselves in an AI-heavy world.', subs: ['human judgment', 'critical thinking', 'becoming harder to replace', 'using AI instead of fearing it', 'avoiding intellectual laziness', 'continuous learning'] },
  { id: 'future_proof_career', name: 'Future-Proof Career', weight: 7, core: 'Build valuable skills instead of depending on titles.', subs: ['skill stacking', 'portfolio over credentials', 'proof of work', 'career reinvention', 'building leverage'] },
  { id: 'digital_detox', name: 'Digital Detox', weight: 8, core: 'Reclaim attention from phones, feeds and algorithms.', subs: ['doomscrolling', 'phone-free mornings', 'notifications', 'creating instead of consuming', 'digital minimalism', 'protecting mental space'] },
  { id: 'slow_living', name: 'Slow Living', weight: 6, core: 'A meaningful life does not have to be rushed.', subs: ['peaceful mornings', 'ordinary moments', 'quality over speed', 'offline hobbies', 'intentional routines'] },
  { id: 'deep_work', name: 'Deep Work & Focus', weight: 7, core: 'Attention is a competitive advantage.', subs: ['single-tasking', 'phone-free work', 'creating before consuming', 'protecting mornings', 'attention management'] },
  { id: 'resilience', name: 'Emotional Resilience', weight: 6, core: 'Strength is the ability to recover and stay grounded.', subs: ['setbacks', 'patience', 'staying calm', 'responding instead of reacting', 'difficult seasons'] },
  { id: 'self_trust', name: 'Self-Trust & Confidence', weight: 4, core: 'Confidence comes from evidence created by your own actions.', subs: ['keeping promises', 'decision-making', 'confidence through action', 'being misunderstood', 'personal standards'] },
  { id: 'small_wins', name: 'Small Wins & Micro Habits', weight: 7, core: 'Small actions compound.', subs: ['1% improvement', 'tiny habits', 'compound effect', 'habit stacking', 'starting small'] },
  { id: 'anti_comparison', name: 'Anti-Comparison', weight: 4, core: 'Stop measuring your life against highlights.', subs: ['different timelines', 'staying in your lane', 'defining your own success', 'comparison traps', 'gratitude'] },
  { id: 'burnout_recovery', name: 'Burnout & Recovery', weight: 4, core: 'Exhaustion is not proof of ambition.', subs: ['rest', 'recovery', 'boundaries', 'energy management', 'sustainable productivity', 'saying no'] },
  { id: 'career_growth', name: 'Career Growth', weight: 5, core: 'Become more valuable before demanding the next title.', subs: ['mentorship', 'professional reputation', 'communication', 'visibility', 'building proof'] },
  { id: 'money_discipline', name: 'Money & Financial Discipline', weight: 3, core: 'Build stability instead of performing wealth. Educational and behavioral only — never specific investment advice.', subs: ['delayed gratification', 'lifestyle inflation', 'quiet wealth', 'spending discipline', 'avoiding status spending'] },
  { id: 'leadership', name: 'Leadership & Character', weight: 2, core: 'Leadership begins with character and self-control.', subs: ['responsibility', 'integrity', 'listening', 'leading by example', 'accountability'] },
  { id: 'boundaries', name: 'Boundaries & Self-Respect', weight: 3, core: 'Protect your time, attention, energy and dignity. No toxic "cut everyone off" messaging.', subs: ['saying no', 'overexplaining', 'people pleasing', 'protecting peace', 'mutual effort'] },
  { id: 'reinvention', name: 'Reinvention & Starting Over', weight: 3, core: 'You are allowed to change direction.', subs: ['new beginnings', 'changing careers', 'rebuilding', 'second chances', 'leaving old versions of yourself'] },
  { id: 'courage', name: 'Courage & Discomfort', weight: 3, core: 'Growth often begins where comfort ends.', subs: ['starting before ready', 'difficult conversations', 'rejection', 'publishing work', 'learning publicly'] },
  { id: 'purpose', name: 'Purpose & Meaning', weight: 2, core: 'Success without meaning can still feel empty.', subs: ['defining success', 'values', 'meaningful work', 'personal philosophy'] },
  { id: 'intentional_life', name: 'Intentional Life', weight: 8, core: 'Stop living on autopilot.', subs: ['intentional choices', 'simplifying life', 'priorities', 'environment design', 'meaningful experiences'] }
];

const HOOK_PATTERNS = ['contrarian', 'observation', 'reframe', 'question', 'paradox', 'direct statement', 'modern problem', 'identity', 'future consequence', 'philosophical'];
const CAPTION_LENGTHS = ['short: 40-80 words', 'medium: 80-150 words', 'long: 150-250 words'];
const FORMATS = ['single image + caption', 'minimal quote poster', 'cinematic image + short statement', 'conceptual visual metaphor', 'question-based image', 'two-line philosophical statement', 'practical micro-advice', 'contrarian insight', 'short educational insight', 'reflection'];
const PALETTES = ['warm earth', 'charcoal + cream', 'muted green', 'deep blue', 'warm amber', 'soft gray monochrome', 'natural wood', 'subtle metallic'];

// Group share pool (user-joined public groups, 2026-08-24). Each published post is assigned the NEXT
// block of 4 groups (consecutive, non-overlapping, wraps around the pool).
const GROUP_POOL = [
  { id: '557093121330339', name: 'Group 01', url: 'https://www.facebook.com/groups/557093121330339/' },
  { id: '3068652839830302', name: 'Group 02', url: 'https://www.facebook.com/groups/3068652839830302/' },
  { id: '1277931033721000', name: 'Group 03', url: 'https://www.facebook.com/groups/1277931033721000/' },
  { id: '224170823053655', name: 'Group 04', url: 'https://www.facebook.com/groups/224170823053655/' },
  { id: '175076773308988', name: 'Group 05', url: 'https://www.facebook.com/groups/175076773308988/' },
  { id: '112168158884874', name: 'Group 06', url: 'https://www.facebook.com/groups/112168158884874/' },
  { id: 'billionairmindsetquotes', name: 'Group 07', url: 'https://www.facebook.com/groups/billionairmindsetquotes/' },
  { id: 'billionairesthinking', name: 'Group 08', url: 'https://www.facebook.com/groups/billionairesthinking/' },
  { id: 'successquotess', name: 'Group 09', url: 'https://www.facebook.com/groups/successquotess/' },
  { id: '1076951029899388', name: 'Group 10', url: 'https://www.facebook.com/groups/1076951029899388/' },
  { id: '186297316379630', name: 'Group 11', url: 'https://www.facebook.com/groups/186297316379630/' },
  { id: '1400779753809224', name: 'Group 12', url: 'https://www.facebook.com/groups/1400779753809224/' },
  { id: '835580721364268', name: 'Group 13', url: 'https://www.facebook.com/groups/835580721364268/' },
  { id: '2498396733824085', name: 'Group 14', url: 'https://www.facebook.com/groups/2498396733824085/' },
  { id: '1936803896580105', name: 'Group 15', url: 'https://www.facebook.com/groups/1936803896580105/' }
];
const GROUPS_PER_POST = 4;

const staticData = null; // memory lives in the CCM Memory Store workflow now
const storeResp = (() => { try { return $('01b Load Memory').first().json || {}; } catch (e) { return {}; } })();
const memory = storeResp.content || [];

// Webhook body overrides (batch size, forced categories, one-off publish) — only present on Manual Fire runs.
const body = (() => { try { return $('Manual Fire').first().json.body || {}; } catch (e) { return {}; } })();
if (body.batch) CONFIG.BATCH_SIZE = Math.min(20, Math.max(1, parseInt(body.batch, 10) || 1));
if (typeof body.publish === 'boolean') CONFIG.AUTO_PUBLISH_ENABLED = body.publish;
const forcedCategories = Array.isArray(body.categories) && body.categories.length ? body.categories.slice(0, 20) : null;

function pickWeighted(exclude) {
  const pool = CATEGORIES.filter(c => !exclude.includes(c.id));
  const list = pool.length ? pool : CATEGORIES;
  let total = 0; for (const c of list) total += c.weight;
  let r = Math.random() * total;
  for (const c of list) { r -= c.weight; if (r <= 0) return c; }
  return list[list.length - 1];
}
// Avoid the categories used by the most recent posts.
const exclude = memory.slice(-2).map(m => String(m.category || '').toLowerCase().replace(/[^a-z]+/g, '_'));
const picked = [];
const n = CONFIG.BATCH_SIZE;
for (let i = 0; i < n; i++) {
  if (forcedCategories) {
    const fc = CATEGORIES.find(c => c.id === forcedCategories[i % forcedCategories.length] || c.name === forcedCategories[i % forcedCategories.length]);
    if (fc) picked.push(fc); else picked.push(pickWeighted(picked.map(p => p.id)));
  } else {
    picked.push(pickWeighted(picked.map(p => p.id)));
  }
}

// Rotation: avoid repeating the last-used values.
function rotate(arr, last) { const pool = arr.filter(v => !last.includes(v)); return (pool.length ? pool : arr)[Math.floor(Math.random() * (pool.length ? pool.length : arr.length))]; }
const styleRotation = picked.map((_, i) => rotate(FORMATS, [])); // format varies freely per post

// Recent content summary for the originality engine (last 15 posts).
const recent = memory.slice(-15).map(m => ({ category: m.category, hook: m.hook, headline: m.headline, angle: m.angle, metaphor: m.visual_concept || m.metaphor }));
// Recent poster layouts so the Creator rotates styles instead of repeating (last 8 that have one).
const recentLayouts = memory.slice(-8).map(m => m.layout).filter(Boolean);

// Group rotation: the Nth post ever stored gets groups [(N*4) .. (N*4+3)] wrapped around the pool.
// storeResp.total = records BEFORE this run, so post i in this batch advances the cursor by 4 each.
const groupTargets = picked.map((_, i) => {
  const start = ((storeResp.total || memory.length) + i) * GROUPS_PER_POST % GROUP_POOL.length;
  return { start,
    groups: Array.from({ length: GROUPS_PER_POST }, (_, k) => GROUP_POOL[(start + k) % GROUP_POOL.length]) };
});

return [{ json: {
  config: CONFIG,
  aspect: ASPECTS[CONFIG.IMAGE_ASPECT_RATIO] || ASPECTS['2:3'],
  picks: picked.map(p => ({ id: p.id, name: p.name, core: p.core, subs: p.subs })),
  captionLength: CONFIG.CAPTION_LENGTH === 'rotate' ? CAPTION_LENGTHS[Math.floor(Math.random() * CAPTION_LENGTHS.length)] : CONFIG.CAPTION_LENGTH + ' words',
  recentContent: recent,
  recentLayouts: recentLayouts,
  groupTargets: groupTargets,
  memoryCount: storeResp.total || memory.length,
  generatedAt: new Date().toISOString()
} }];

// 04 Editorial Strategy — builds the editorial mega-prompt from config, trend context and content memory.
const cfg = $('01 Config & Memory').first().json;

// Trend context from the merged sources (Pinterest RSS titles + Hacker News).
let trends = [];
for (const item of $input.all()) {
  const j = item.json;
  const raw = typeof j === 'string' ? j : (j.data || JSON.stringify(j));
  if (raw && raw.charAt(0) === '<') {
    const items = [...raw.matchAll(/<item>[\s\S]*?<\/item>/g)].slice(0, 8);
    for (const m of items) {
      const t = (m[0].match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [])[1];
      if (t && t.length > 8) trends.push(t.trim());
    }
  } else if (j && j.hits) {
    for (const h of j.hits.slice(0, 8)) if (h.title) trends.push(h.title);
  }
}
trends = [...new Set(trends)].slice(0, 12);

const VISUAL_STYLES = {
  'cinematic human': 'human subject in dramatic environment, realistic photography, cinematic lighting, shallow depth of field, premium editorial (good: discipline, resilience, confidence, courage)',
  'luxury editorial': 'architectural interiors, premium materials, sophisticated workspace, black/cream neutrals, controlled composition (good: quiet ambition, career, money, leadership)',
  'nature philosophy': 'mountains, forests, ocean, roads, trees, sunrise, fog, rain (good: growth, patience, purpose, resilience)',
  'analog offline': 'notebooks, books, film cameras, coffee, wooden desks, handwritten notes, warm natural light (good: digital detox, slow living, focus, intentional life)',
  'futuristic human': 'subtle futuristic architecture, sophisticated technology aesthetic, human silhouette, cinematic light — never cheesy sci-fi (good: AI-era growth, future careers, adaptability)',
  'minimal typography': 'extremely simple background, strong negative space, minimal objects, editorial poster design (good: boundaries, confidence, self-respect, philosophy)',
  'transformation': 'visual metaphor of change: seed to tree, darkness to light, closed door to open landscape, storm to calm (good: reinvention, growth, recovery, starting over)'
};
const METAPHOR_LIBRARY = {
  growth: ['seed becoming a tree', 'tree rings', 'staircase', 'mountain trail at dawn', 'construction site', 'sunrise'],
  focus: ['single spotlight', 'isolated desk', 'one straight road', 'clean workspace'],
  digital_detox: ['phone face down', 'device in a drawer', 'person outdoors without a phone', 'paper notebook'],
  reinvention: ['open door', 'crossroads', 'new road', 'broken wall with light behind'],
  resilience: ['tree bent by wind still standing', 'storm clearing', 'ocean after rain', 'mountain in clouds'],
  quiet_ambition: ['late-night office light', 'empty early workspace', 'blueprint on a desk', 'unfinished structure rising']
};
const HOOK_EXAMPLES = {
  'contrarian': 'Being busy is not the same as moving forward.',
  'observation': 'Most people don\'t lose focus all at once. They lose it notification by notification.',
  'reframe': 'Rest isn\'t the opposite of discipline. Sometimes it\'s what makes discipline sustainable.',
  'question': 'What would change if you stopped trying to impress people who aren\'t building your life?',
  'paradox': 'The fastest way to burn out is to treat every day like a deadline.',
  'direct statement': 'Build quietly.',
  'modern problem': 'Your biggest distraction may fit inside your pocket.',
  'identity': 'Become the person who keeps promises to themselves.',
  'future consequence': 'The habits you ignore today become the life you inherit later.',
  'philosophical': 'A peaceful life can still be an ambitious life.'
};

const styleKeys = Object.keys(VISUAL_STYLES);
const styleGuide = cfg.picks.map((p, i) => {
  const style = styleKeys[(cfg.memoryCount + i) % styleKeys.length]; // deterministic rotation across posts
  return 'POST ' + (i + 1) + ' must use visual style "' + style + '": ' + VISUAL_STYLES[style];
}).join('\n');

const prompt = 'You are the editorial engine of a premium self-improvement page. Niche: "Modern self-improvement for ambitious people living in a noisy, digital, AI-heavy world." Voice: calm, intelligent, mature, concise, emotionally strong, modern, reflective, confident. NEVER generic motivational-speaker content, no hustle shouting, no excessive emojis (max 1, usually 0), no fake stories, no fake statistics, no invented research, no engagement bait.\n\n'
+ 'PLATFORM: ' + cfg.config.PLATFORM + ' (adapt caption depth/tone to it).\n'
+ 'Generate ' + cfg.picks.length + ' COMPLETELY DIFFERENT posts, one per category below. For EACH post internally generate 3-5 candidate concepts, evaluate them for originality/emotional impact/visual potential/non-cliche quality, and output ONLY the strongest one per category.\n\n'
+ 'CATEGORIES FOR THIS RUN:\n' + cfg.picks.map((p, i) => 'POST ' + (i + 1) + ' — ' + p.name + ' (core idea: ' + p.core + '). Pick ONE subtopic/angle: ' + p.subs.join('; ') + '. The post must express ONE specific content angle (a concrete insight, not a vague theme).').join('\n') + '\n\n'
+ (cfg.config.TREND_RESEARCH_ENABLED && trends.length ? 'TREND CONTEXT (recent titles from this niche — get the vibe of what people discuss, NEVER copy wording):\n' + trends.join('\n') + '\n\n' : '')
+ 'HOOK SYSTEM: rotate hook styles across posts. Styles with examples: ' + Object.entries(HOOK_EXAMPLES).map(([k, v]) => k + ' ("' + v + '")').join('; ') + '. Assign a DIFFERENT hook style to each post.\n'
+ 'VISUAL METAPHOR LIBRARY (draw from these for the poster subject, never repeat the same metaphor as recent content): ' + Object.entries(METAPHOR_LIBRARY).map(([k, v]) => k + ': ' + v.join(', ')).join(' | ') + '\n'
+ 'COLOR: the poster system is monochrome + ONE accent per image — choose the accent to fit the emotion (warm gold = legacy/time/value, deep crimson = power/urgency, golden-yellow = predator focus). Never rainbow, never pastel.\n\n'
+ 'PREMIUM VALUE-POSTER SYSTEM (CRITICAL): Every post generates an image that contains COMPLETE READABLE VALUE. The viewer should be able to read the image text alone in 5 seconds, understand the entire lesson, and immediately want to save/like the post.\n'
+ 'For EVERY post provide an "image" object with:\n'
+ '- "layout": one of the twelve visual layouts (isolated_beast, duality_split, matrix_grid, infographic, dark_icon, impossible_breakthrough, tension_snap, surreal_state_change, transformative_reflection, corrupting_touch, degradation_split, inevitable_loop)\n'
+ '- "subject": rich visual description of the symbolic objects/scene/metaphor — no humans, no faces\n'
+ '- "accent": single accent color (e.g. golden-yellow, deep crimson, warm gold, emerald green, amber)\n'
+ '- "headline": 2-5 WORDS, ALL CAPS, punchy concept title (e.g. "THE LAW OF SILENT LEVERAGE" or "THE COST OF PROVING YOURSELF")\n'
+ '- "insight_body": 2-3 COMPLETE, PROFOUND, HIGH-VALUE SENTENCES explaining the core insight directly on the image so the viewer gets the full meaning instantly without opening the caption.\n'
+ '- "takeaway": ONE sharp concluding rule/truth line (e.g. "Rule: Value privacy over applause." or "Truth: Real power never has to shout.")\n'
+ '- "subtext": short fallback combination of insight_body and takeaway\n'
+ 'plus layout extras (duality_split: left_text, right_text, left_subject, right_subject; matrix_grid: accent_word; infographic: items and closing_line; transformative_reflection: reflection_subject; degradation_split: destroyer; impossible_breakthrough: surface).\n\n'
+ 'IMAGE/CAPTION RULE: The image contains the full core value lesson. The caption expands upon it with deeper nuance and context.\n\n'
+ 'CAPTION LENGTH: ' + cfg.captionLength + '.\n'
+ 'CTA: include a natural, non-bait CTA on roughly ' + Math.round(cfg.config.CTA_FREQUENCY * 100) + '% of posts (question inviting genuine reflection); empty string "" otherwise.\n'
+ 'HASHTAGS: 3-' + cfg.config.HASHTAG_LIMIT + ' highly relevant (core niche + topic), lowercase with #, no generic viral stuffing.\n\n'
+ (cfg.recentContent.length ? 'ORIGINALITY CONTEXT — recent posts already published (DO NOT repeat their hooks, headlines, angles, metaphors or wording; your output must be clearly distinct):\n' + cfg.recentContent.map(r => '- [' + r.category + '] hook: "' + r.hook + '" | headline: "' + (Array.isArray(r.headline) ? r.headline.join(' / ') : r.headline) + '" | angle: ' + r.angle).join('\n') + '\n\n' : '')
+ 'Return ONLY valid JSON:\n{"posts":[{"content_id":"' + Date.now() + '-N","category":"","subcategory":"","trend_context":"one line on the underlying human concern (or empty)","content_angle":"","hook_style":"","hook":"","subheadline":"","core_message":"","visual_style":"","visual_concept":"","metaphor":"","image":{"layout":"","subject":"","accent":"","headline":"","insight_body":"","takeaway":"","subtext":"","accent_word":"","left_text":"","right_text":"","left_subject":"","right_subject":"","closing_line":"","reflection_subject":"","destroyer":"","items":[{"label":"","object":""}]},"caption":"","cta":"","hashtags":["#"],"platform":"' + cfg.config.PLATFORM + '","self_quality_score":0}]}';

const payload = { model: 'gpt-5', messages: [{ role: 'user', content: prompt }], response_format: { type: 'json_object' } };
const ollamaPayload = { model: 'llama3.1:8b', prompt: prompt, format: 'json', stream: false, options: { temperature: 0.85 } };

return [{ json: { payload: payload, ollamaPayload: ollamaPayload, meta: { batch: cfg.picks.length, trendCount: trends.length, at: cfg.generatedAt } } }];

// 06 Parse & Validate — schema validation, cliché + duplicate detection, poster-prompt assembly (gpt-image-2 style engine).
const cfgData = $('01 Config & Memory').first().json;
const CONFIG = cfgData.config;

let ai = {};
try {
  const resp = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || $json.response || ($json.candidates && $json.candidates[0].content.parts[0].text) || '{}';
  ai = typeof resp === 'string' ? JSON.parse(resp) : resp;
} catch (e) { throw new Error('AI returned non-JSON: ' + String($json.response || $json.choices || '').substring(0, 200)); }

const posts = ai.posts || (Array.isArray(ai) ? ai : []);
if (!posts.length) throw new Error('AI returned no posts');

// Cliché detection (banned generic phrases; allowed only if genuinely subverted).
const CLICHES = ['never give up', 'believe in yourself', 'dream big', 'work hard', 'stay positive', 'success takes time', 'everything happens for a reason', 'you can do anything', 'keep pushing', 'be yourself', 'great things take time', 'hustle harder'];
const memory = (() => { try { return ($('01b Load Memory').first().json || {}).content || []; } catch (e) { return []; } })();

// Jaccard word-overlap similarity for duplicate detection.
function tokens(s) { return new Set(String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 3)); }
function similarity(a, b) {
  const A = tokens(a), B = tokens(b);
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const w of A) if (B.has(w)) inter++;
  return inter / (A.size + B.size - inter);
}

// ── PREMIUM POSTER STYLE KIT (proven 2026-08-24, variants A–J + user-supplied conceptual blueprints) ──
// To add a new style later: append a template below + describe it in the 04 strategy prompt.
const POSTER_BASE = 'A highly realistic, premium minimalist social media editorial graphic. ';
const POSTER_NEG = ' Avoid: messy background, lifestyle photography, humans, cafes, offices, cluttered desk, busy city, generic motivational poster, cursive fonts, cartoon, illustration, 3d render, plastic, low resolution, misspelled text, rainbow colors, pastels, vintage, sepia, text covering the subject.';
const q = t => String(t || '').replace(/"/g, "'").trim();

const POSTER_TEMPLATES = {
  isolated_beast: im =>
    'LAYOUT STYLE: The Value Poster. SUBJECT: ' + q(im.subject) + ', placed gracefully in the lower half. BACKGROUND: Pure studio white with a subtle soft grey gradient. LIGHTING: Dramatic high-contrast studio lighting, sharp shadows. COLOR GRADING: Monochrome white and charcoal with a single ' + q(im.accent || 'golden-yellow') + ' accent. TYPOGRAPHY AND FULL VALUE TEXT: In the clean upper negative space, bold uppercase concept title reading exactly: "' + q(im.headline) + '" followed by full readable insight text in crisp modern typography reading exactly: "' + q(im.insight_body || im.subtext) + '" and concluding with takeaway rule line reading exactly: "' + q(im.takeaway || '') + '" TEXT PLACEMENT: Upper half, perfectly centered, pristine typography, high contrast, 100% readable. AESTHETIC: Masterpiece, 8k, photorealistic, advertising photography, crisp edges, immaculate negative space.',
  duality_split: im =>
    'LAYOUT STYLE: The Duality Split. SUBJECT: A perfect 50/50 vertical split image. LEFT half: pure white background with ' + q(im.left_subject) + '. RIGHT half: pitch black background with ' + q(im.right_subject) + '. LIGHTING: High contrast, sharp studio light on both subjects. COLOR GRADING: Pure black and pure white only. TYPOGRAPHY AND FULL VALUE TEXT: Color-inverted editorial typography reading exactly "' + q(im.left_text) + '" in black text on the white left side and "' + q(im.right_text) + '" in white text on the black right side, both with readable insight subtext below: "' + q(im.insight_body || im.subtext) + '" AESTHETIC: Masterpiece, 8k, photorealistic, advertising photography, crisp edges, immaculate negative space.',
  matrix_grid: im =>
    'LAYOUT STYLE: The Matrix Textured Grid. SUBJECT: ' + q(im.subject) + ', its form partly formed from shattered bold typographic letterforms. BACKGROUND: Stark white fading into light grey texture. LIGHTING: High contrast studio lighting, stark shadows. COLOR GRADING: Monochrome black and white with a deep crimson red accent. TYPOGRAPHY AND FULL VALUE TEXT: Massive bold sans-serif headline reading: "' + q(im.headline) + '" with full value insight text clearly rendered below reading: "' + q(im.insight_body || im.subtext) + '" and rule line: "' + q(im.takeaway || '') + '" AESTHETIC: Masterpiece, 8k, photorealistic, advertising photography, crisp edges, immaculate negative space.',
  infographic: im => {
    const items = (im.items || []).slice(0, 4);
    const objs = items.map((it, i) => (i + 1) + '. ' + q(it.object)).join(', ');
    const labels = items.map(it => '"' + q(it.label) + '"').join(', ');
