  // Eon Ventures
  'discipline_no_hustle': { id: '1077306835630491', name: 'Eon Ventures' },
  'small_wins': { id: '1077306835630491', name: 'Eon Ventures' },
  'courage': { id: '1077306835630491', name: 'Eon Ventures' },
