  'reinvention': { id: '106473735839651', name: 'The Boundaries Club' }
};

// Normalize the AI's image spec: valid layout with required fields, else graceful fallback.
function buildImageSpec(p) {
  const im = p.image || {};
  let layout = POSTER_TEMPLATES[im.layout] ? im.layout : 'isolated_beast';
  if (layout === 'duality_split' && !(im.left_text && im.right_text && im.left_subject && im.right_subject)) layout = 'isolated_beast';
  if (layout === 'infographic' && (!Array.isArray(im.items) || im.items.length < 3)) layout = 'dark_icon';
  if (layout === 'transformative_reflection' && !im.reflection_subject) layout = 'dark_icon';

  const headline = String(im.headline || p.hook || 'FOCUS.').substring(0, 50).toUpperCase();
  const insight_body = String(im.insight_body || p.core_message || p.subheadline || '').substring(0, 200);
  const takeaway = String(im.takeaway || '').substring(0, 80);
  const subtext = insight_body + (takeaway ? ' ' + takeaway : '');

  const spec = { ...im, layout,
    subject: String(im.subject || p.visual_concept || p.metaphor || 'a powerful symbolic scene'),
    headline: headline,
    insight_body: insight_body,
    takeaway: takeaway,
    subtext: subtext,
    accent: im.accent || (layout === 'matrix_grid' ? 'deep crimson' : (layout === 'tension_snap' ? 'white and gold' : 'warm gold'))
  };

  spec.expectedText = 'the headline "' + q(spec.headline) + '" and the readable insight text "' + q(spec.insight_body || spec.subtext).substring(0, 100) + '"';
  const neg = layout === 'inevitable_loop' ? POSTER_NEG.replace('3d render, ', '') : POSTER_NEG;
  const prompt = POSTER_BASE + POSTER_TEMPLATES[layout](spec) + neg;
  return { spec, prompt };
}

const out = [];
for (let pi = 0; pi < posts.length; pi++) {
  const p = posts[pi];
  const catKey = String(p.category || '').toLowerCase().replace(/[^a-z0-9]+/g, '_');
  const targetPage = PAGE_ROUTING[catKey] || { id: '114550268199751', name: 'Reliq North' };

  const errors = [];
  if (!p.hook) errors.push('missing hook');
  if (!p.image || !p.image.headline) errors.push('missing image.headline');
  if (!p.caption || p.caption.length < 40) errors.push('caption too short');
  const text = (p.hook + ' ' + ((p.image && p.image.headline) || '') + ' ' + p.caption).toLowerCase();
  const clicheHits = CLICHES.filter(c => text.includes(c));

  // Duplicate check vs memory (hook + image headline + caption combined).
  const candidateText = p.hook + ' ' + ((p.image && p.image.headline) || '') + ' ' + p.caption;
  let maxSim = 0, simVs = '';
  for (const m of memory.slice(-40)) {
    const s = similarity(candidateText, (m.hook || '') + ' ' + (m.image_headline || m.headline || '') + ' ' + (m.caption || ''));
    if (s > maxSim) { maxSim = s; simVs = m.content_id || ''; }
  }
  const duplicate = maxSim >= CONFIG.SIMILARITY_THRESHOLD;

  const { spec: imageSpec, prompt: imagePrompt } = buildImageSpec(p);
  const caption = (p.hook ? p.hook + '\n\n' : '') + (p.caption || '') + (p.cta ? '\n\n' + p.cta : '') + ((p.hashtags || []).length ? '\n\n' + (p.hashtags || []).join(' ') : '');

  const post = {
    content_id: p.content_id || (Date.now() + '-' + Math.random().toString(36).slice(2, 7)),
    category: p.category || '', subcategory: p.subcategory || '', trend_context: p.trend_context || '',
    angle: p.content_angle || '', hook_style: p.hook_style || '', hook: p.hook || '',
    headline: [imageSpec.headline], subheadline: p.subheadline || '', core_message: p.core_message || '',
    visual_style: p.visual_style || '', visual_concept: p.visual_concept || p.metaphor || '', metaphor: p.metaphor || '',
    caption_full: caption, cta: p.cta || '', hashtags: p.hashtags || [],
    self_quality_score: p.self_quality_score || 0,
    targetPage: targetPage,
    validation: { errors, clicheHits, maxSimilarity: Math.round(maxSim * 100) / 100, duplicate, simVs },
    imageSpec: imageSpec,
    imagePrompt: imagePrompt,
    imageGenPayload: { model: 'gpt-image-2', prompt: imagePrompt, size: CONFIG.IMAGE_SIZE || '1024x1536', n: 1 },
    group_targets: (cfgData.groupTargets && cfgData.groupTargets[pi]) || null,
    fbUrl: 'https://graph.facebook.com/v20.0/' + targetPage.id + '/photos?access_token=' + encodeURIComponent($env.FB_PAGE_TOKEN) + '&caption=' + encodeURIComponent(caption),
    qcPayload: {
      model: 'gpt-5',
      messages: [{ role: 'user', content: 'You are a strict quality-control editor for a premium self-improvement page (calm, intelligent, modern voice; niche: modern self-improvement for ambitious people in a noisy AI-heavy world). Score this post 0-100. Breakdown: originality 0-20, clarity 0-15, emotional impact 0-15, usefulness 0-15, shareability 0-10, visual strength 0-10, brand fit 0-10, non-cliche quality 0-5. Post:\nCATEGORY: ' + p.category + '\nPAGE: ' + targetPage.name + '\nANGLE: ' + p.content_angle + '\nHOOK (' + p.hook_style + '): ' + p.hook + '\nPOSTER: layout ' + imageSpec.layout + ' — headline "' + imageSpec.headline + '" / insight "' + imageSpec.insight_body + '" / takeaway "' + imageSpec.takeaway + '"\nCAPTION: ' + p.caption + '\nCTA: ' + (p.cta || 'none') + '\nReturn ONLY JSON: {"score":0,"subs":{"originality":0,"clarity":0,"emotional_impact":0,"usefulness":0,"shareability":0,"visual_strength":0,"brand_fit":0,"non_cliche":0},"verdict":"approve|reject","critique":"one sentence"}' }],
      response_format: { type: 'json_object' }
    }
  };
  out.push({ json: post });
}
return out;

// 10 Save Draft — attach the persistence record + compute the publish gate, pass everything through (binary preserved).
// Publish requires ALL of: AUTO_PUBLISH_ENABLED (config or webhook override), image generated, vision QA passed.
const CONFIG = $('01 Config & Memory').first().json.config;
for (const item of $input.all()) {
  const p = $('06 Parse & Validate').item.json;
  const qc = (() => { try { return $('08 QC Parse').item.json; } catch (e) { return {}; } })();
  const v = item.json || {};
  const hasImage = !!(item.binary && item.binary.data);
  const publishApproved = !!(CONFIG.AUTO_PUBLISH_ENABLED && v.visionOk && hasImage);
  const publishBlockReason = publishApproved ? '' :
    (!CONFIG.AUTO_PUBLISH_ENABLED ? 'auto_publish_off' :
     (!hasImage ? 'image_generation_failed' :
      'vision_qa_failed: ' + String(v.visionIssues || 'mismatch').substring(0, 120)));
  item.json = {
    ...item.json,
    publishApproved,
    publishBlockReason,
    storeRecord: {
      content_id: p.content_id,
      created_at: new Date().toISOString(),
      category: p.category, subcategory: p.subcategory, trend_context: p.trend_context,
      angle: p.angle, hook_style: p.hook_style, hook: p.hook,
      headline: (p.headline || []).join(' / '), core_message: p.core_message,
      layout: p.imageSpec.layout, image_headline: p.imageSpec.headline, image_subtext: p.imageSpec.subtext,
      visual_style: p.visual_style, visual_concept: p.visual_concept, format: 'premium-poster/' + p.imageSpec.layout,
      caption: p.caption_full, cta: p.cta, hashtags: (p.hashtags || []).join(' '),
      qc_score: qc.score || null,
      vision_ok: v.visionOk === true,
      group_targets: (p.group_targets && p.group_targets.groups || []).map(g => g.url),
      status: 'draft',
      platform: CONFIG.PLATFORM
    }
  };
}
return $input.all();

// 12 Log & Done — final run report (no local storage; persistence happens via the memory store).
const fb = $json || {};
const feedPostId = (() => { try { return ($('Post to Facebook').first().json || {}).post_id || null; } catch (e) { return null; } })();
const postId = feedPostId || fb.post_id || fb.id || null;
const fbError = fb.error ? (fb.error.message || 'facebook error').substring(0, 120) : null;
const pack = $json.sharePack || null;
const reelId = (() => { try { return ($('15 Publish Reel').first().json || {}).id || null; } catch (e) { return null; } })();
const storyOk = (() => { try { return $('18 Publish Story').first().json.success === true; } catch (e) { return false; } })();
return [{ json: {
  loggedAt: new Date().toISOString(),
  facebook: postId ? { post_id: postId } : (fbError ? { error: fbError } : { skipped: $json.publishBlockReason || 'not published — saved as draft in the CCM Memory Store' }),
  reel: reelId ? { video_id: reelId } : null,
  story: storyOk ? { published: true } : null,
  share_pack: pack ? { post: pack.post_permalink, headline: pack.headline, share_into_groups: pack.share_into_groups } : null
} }];

// 10r Save Rejected — build the rejection record (storage happens in "10r2 Store Rejected" HTTP node).
const CONFIG = $('01 Config & Memory').first().json.config;
const out = [];
for (const item of $input.all()) {
  const src = $('06 Parse & Validate').item.json;
  const qc = item.json || {};
  out.push({ json: { storeRecord: {
    content_id: src.content_id,
    created_at: new Date().toISOString(),
    category: src.category, subcategory: src.subcategory,
    angle: src.angle, hook: src.hook, headline: (src.headline || []).join(' / '),
    caption: src.caption_full, visual_style: src.visual_style,
    qc_score: qc.score || null, critique: qc.critique || '',
    similarity: src.validation ? src.validation.maxSimilarity : null,
    status: 'rejected', reason: src.validation && src.validation.duplicate ? 'duplicate' : 'quality',
    platform: CONFIG.PLATFORM
  } } });
}
return out;

// 08 QC Parse — unpack EACH gpt-5 quality-control response (choices[0].message.content) into {score, verdict, critique}.
const out = [];
for (const item of $input.all()) {
  let qc = {};
  try {
    const j = item.json;
    const raw = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || j.response || '{}';
    qc = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    qc = { score: 0, verdict: 'reject', critique: 'QC response unparseable: ' + String(e.message).substring(0, 100) };
  }
  out.push({ json: { score: typeof qc.score === 'number' ? qc.score : 0, subs: qc.subs || {}, verdict: qc.verdict || 'reject', critique: qc.critique || '' } });
}
return out;

// 07b Decode Image — turn gpt-image-2 b64 into binary + data URI, carry poster fields forward.
const out = [];
for (const item of $input.all()) {
  const b64 = item.json && item.json.data && item.json.data[0] && item.json.data[0].b64_json;
  const p = $('06 Parse & Validate').item.json;
  if (!b64) {
    out.push({ json: { imageOk: false, error: String(item.json && item.json.error && item.json.error.message || 'no image data').substring(0, 150),
      expectedText: p.imageSpec.expectedText, content_id: p.content_id } });
    continue;
  }
  out.push({ json: { imageOk: true, dataUri: 'data:image/jpeg;base64,' + b64,
    expectedText: p.imageSpec.expectedText,
    content_id: p.content_id, caption: p.caption_full, fbUrl: p.fbUrl },
    binary: { data: { data: b64, mimeType: 'image/jpeg', fileName: 'poster-' + p.content_id + '.jpg' } } });
}
return out;

