      expectedText: dec.json.expectedText,
      content_id: dec.json.content_id, caption: dec.json.caption, fbUrl: dec.json.fbUrl },
    binary: b64 ? { data: { data: b64, mimeType: 'image/jpeg', fileName: 'poster.jpg' } } : undefined
  });
}
return out;

